        "narration": "로마의 유일한 미슐랭 3스타 레스토랑 라 페르골라에서 숨막히는 전망과 정교한 오뜨 퀴진을 경험하세요.",
        "description": "파노라마 뷰를 갖춘 미슐랭 3스타 파인 다이닝",
