    "translations": {
      "ko": {
        "name": "로마의 맛집 골목",
        "description": "로컬 테스트용 맛집 거리",
        "narration": "현지인들만 아는 비밀스러운 맛집들이 모여있는 곳입니다. 데모 모드에서는 AI가 직접 생성한 것처럼 보이지만, 사실 시스템이 제공하는 안전한 테스트 데이터란다. 맛있어 보이는 음식 사진들이 눈앞에 그려지지 않니?"
      }
    },
