        "description": "提供意大利美味的美食熟食店和餐厅",
        "detailedDescription": "Roscioli将美食熟食店与精致餐厅结合在罗马市中心。以其出色的意大利奶酪、腌肉和葡萄酒选择而闻名，这家餐厅提供独特的用餐体验。餐厅菜单使用最优质的食材，对传统罗马菜肴进行创意诠释。葡萄酒单非常丰富，拥有超过300个品牌。亲密的用餐室营造出温馨的氛围，非常适合寻求正宗意大利风味的美食爱好者。"
